-- EduNova v0.25.0 LOT 24 — Assignments, Submissions & Intelligent Grading.
CREATE TABLE campus_assignments(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,offering_id varchar(64) NOT NULL REFERENCES teaching_offerings(id) ON DELETE RESTRICT,title varchar(240) NOT NULL,instructions varchar(12000) NOT NULL DEFAULT '',kind varchar(24) NOT NULL CHECK(kind IN ('individual','group')),opens_at timestamptz,due_at timestamptz NOT NULL,closes_at timestamptz,max_attempts integer NOT NULL CHECK(max_attempts>0),max_score double precision NOT NULL CHECK(max_score>0),state varchar(32) NOT NULL CHECK(state IN ('draft','scheduled','published','closed','grading','results_published','archived')),row_version integer NOT NULL CHECK(row_version>0),created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(opens_at IS NULL OR opens_at<due_at),CHECK(closes_at IS NULL OR closes_at>=due_at));
CREATE TABLE assignment_rubric_criteria(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,position integer NOT NULL CHECK(position>0),label varchar(240) NOT NULL,description varchar(4000) NOT NULL DEFAULT '',max_points double precision NOT NULL CHECK(max_points>0),created_at timestamptz NOT NULL,UNIQUE(assignment_id,position));
CREATE TABLE assignment_submissions(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,student_account_id varchar(64) NOT NULL,group_key varchar(128),attempt_no integer NOT NULL CHECK(attempt_no>0),text_content varchar(30000) NOT NULL DEFAULT '',attachment_refs varchar(12000) NOT NULL DEFAULT '',state varchar(24) NOT NULL CHECK(state IN ('draft','submitted','late','returned','graded')),submitted_at timestamptz,row_version integer NOT NULL CHECK(row_version>0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(assignment_id,student_account_id,attempt_no));
CREATE TABLE assignment_grading_decisions(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,submission_id varchar(64) NOT NULL UNIQUE REFERENCES assignment_submissions(id) ON DELETE RESTRICT,proposed_score double precision,final_score double precision,feedback varchar(12000) NOT NULL DEFAULT '',criterion_scores varchar(12000) NOT NULL DEFAULT '',confidence double precision,proposal_source varchar(48) NOT NULL,validated_by varchar(64),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(confidence IS NULL OR (confidence>=0 AND confidence<=1)));
CREATE TABLE assignment_similarity_flags(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,assignment_id varchar(64) NOT NULL REFERENCES campus_assignments(id) ON DELETE RESTRICT,submission_a_id varchar(64) NOT NULL REFERENCES assignment_submissions(id) ON DELETE RESTRICT,submission_b_id varchar(64) NOT NULL REFERENCES assignment_submissions(id) ON DELETE RESTRICT,score double precision NOT NULL CHECK(score>=0 AND score<=1),review_state varchar(24) NOT NULL,created_at timestamptz NOT NULL,CHECK(submission_a_id<>submission_b_id));
CREATE INDEX ix_assignment_due ON campus_assignments(institution_id,offering_id,state,due_at);
CREATE INDEX ix_submission_student ON assignment_submissions(institution_id,student_account_id,assignment_id,state);
CREATE INDEX ix_submission_assignment ON assignment_submissions(institution_id,assignment_id,state,submitted_at);
CREATE INDEX ix_similarity_review ON assignment_similarity_flags(institution_id,assignment_id,review_state,score);
